import { chromium } from '@playwright/test';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { resolve, basename } from 'node:path';

const endpoint = 'http://127.0.0.1:9224';
const browser = await chromium.connectOverCDP(endpoint);
const page = browser.contexts().flatMap((context) => context.pages()).find((page) => page.url() === 'http://127.0.0.1:3104/');
if (!page) throw new Error('Owned original page is absent.');
const session = await page.context().newCDPSession(page);
const contexts = [], scripts = [];
session.on('Runtime.executionContextCreated', ({ context }) => contexts.push(context));
session.on('Debugger.scriptParsed', (script) => scripts.push(script));
const digest = (bytes) => createHash('sha256').update(bytes).digest('hex');
const result = { capturedAt: new Date().toISOString(), endpoint, target: page.url(), method: 'Passive CDP Debugger inventory/getScriptSource. No page evaluation, navigation or original inputs.', contexts, scripts: [], limitations: ['CDP-exposed bytes and script inventory are not complete-module execution coverage or wire provenance.', 'This preloader runtime observation does not retroactively attribute earlier creator captures.'] };
try {
  await session.send('Runtime.enable');
  const { frameTree } = await session.send('Page.getFrameTree');
  result.frame = { id: frameTree.frame.id, url: frameTree.frame.url };
  await session.send('Debugger.enable', { maxScriptsCacheSize: 64 * 1024 * 1024 });
  for (const script of scripts.filter((script) => script.scriptLanguage === 'WebAssembly' || script.url.startsWith('http://127.0.0.1:3104/ruffle/'))) {
    const record = { scriptId: script.scriptId, url: script.url, language: script.scriptLanguage, executionContextId: script.executionContextId, producerHash: script.hash, length: script.length, sourceMapURL: script.sourceMapURL };
    try {
      const source = await session.send('Debugger.getScriptSource', { scriptId: script.scriptId });
      const bytes = source.bytecode ? Buffer.from(source.bytecode, 'base64') : Buffer.from(source.scriptSource, 'utf8');
      record.content = { representation: source.bytecode ? 'CDP-exposed-WASM-bytecode' : 'CDP-scriptSource-UTF8', bytes: bytes.length, sha256: digest(bytes) };
      const candidates = script.scriptLanguage === 'WebAssembly'
        ? ['172de42e6619eac8f371.wasm', '878d548199cddef07035.wasm']
        : [basename(new URL(script.url).pathname)];
      record.installedComparisons = [];
      for (const name of candidates) {
        const installed = await readFile(resolve('node_modules/@ruffle-rs/ruffle', name));
        const sha256 = digest(installed);
        record.installedComparisons.push({ name, bytes: installed.length, sha256, matchesObserved: sha256 === record.content.sha256 });
      }
    } catch (error) {
      record.contentError = String(error);
    }
    result.scripts.push(record);
  }
} finally {
  await session.detach();
  // Disconnect this CDP client. The owning reference-browser process remains responsible for closure.
  await browser.close();
}
await writeFile('reference-captures/runtime-module-observation/loaded-modules.json', JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify({ scripts: result.scripts, frame: result.frame, contexts: result.contexts.map((context) => ({ id: context.id, origin: context.origin, auxData: context.auxData })), limitations: result.limitations }, null, 2));

